export function qualifiedSupplementSkeleton(raw:string,name:string):string {
    const receipt=compilerReceipts[name as keyof typeof compilerReceipts];
    if(!receipt || raw!==receipt.raw)throw new Error('Unqualified supplement compiler skeleton: '+name);
    const skeleton=raw.slice(receipt.prefix.length,-receipt.suffix.length);
    let result='',cursor=0;
    for(const edit of receipt.edits){
        if(edit.start<cursor || skeleton.slice(edit.start,edit.end)!==edit.before)throw new Error('Unqualified supplement static lexical coordinate: '+name);
        result+=skeleton.slice(cursor,edit.start)+edit.after;cursor=edit.end;
    }
    return result+skeleton.slice(cursor);
}

