interface AttributeSlot {field:string;opening:string;needle:string}
function insertSupplementSlots(raw:string,name:string,branch:number,view:object,expectedFields:readonly string[],attributes:readonly AttributeSlot[]):string {
    const prefix='<!--[--><!--['+branch+'-->',suffix='<!--]--><!--]-->';
    if(!raw.startsWith(prefix)||!raw.endsWith(suffix))throw new Error('Unqualified supplement SSR envelope: '+name);
    const skeleton=qualifiedSupplementSkeleton(raw,name);
    // Only the exact locally authored label-ignore comments may occur in this private static skeleton.
    const comments=[...skeleton.matchAll(/<!--[\s\S]*?-->/g)];
    if(comments.length||skeleton.includes('<!>'))throw new Error('Unqualified supplement interior marker: '+name);
    const fields=Reflect.ownKeys(view);
    if(fields.length!==expectedFields.length||fields.some(field=>typeof field!=='string'||!expectedFields.includes(field)))throw new Error('Unqualified supplement field schema');
    // Prepared primitive fields follow the authored schema, independently of object insertion order.
    // Inspect data properties without executing a getter or coercing a provider/user object.
    const values=expectedFields.map(field=>{
        const value:unknown=Object.getOwnPropertyDescriptor(view,field)?.value;
        if(typeof value!=='string')throw new Error('Supplement slot must be prepared text');
        return [field,value] as const;
    });
    const replacements:Array<{start:number;end:number;value:string}>=[];
    for(const [field,value] of values){
        const token='getbased-supplement-'+name+'-'+field+'-private';
        const attribute=attributes.find(slot=>slot.field===field);
        let start:number,end:number;
        if(attribute){
            const ownedOpening=attribute.opening;
            const opening=skeleton.indexOf(ownedOpening);
            if(opening<0||skeleton.indexOf(ownedOpening,opening+1)!==-1)throw new Error('Unqualified supplement owned opening tag');
            const offset=attribute.opening.indexOf(attribute.needle);
            if(offset<0||attribute.opening.indexOf(attribute.needle,offset+1)!==-1)throw new Error('Unqualified supplement attribute coordinate');
            start=opening+offset;end=start+attribute.needle.length;
        }else if(['unitOptions','categories','scheduleOptions','routeOptions','evidenceScopeOptions'].includes(field)){
            const ownedOption='<option data-supplement-private-options="'+token+'"></option>';
            start=skeleton.indexOf(ownedOption);
            if(start<0||skeleton.indexOf(ownedOption,start+1)!==-1)throw new Error('Unqualified supplement option-list coordinate');
            end=start+ownedOption.length;
        }else{
            start=skeleton.indexOf(token);
            if(start<0||skeleton.indexOf(token,start+1)!==-1)throw new Error('Unqualified supplement scalar coordinate');
            end=start+token.length;
        }
        replacements.push({start,end,value});
    }
    replacements.sort((a,b)=>a.start-b.start);
    if(replacements.some((slot,i)=>i>0&&slot.start<replacements[i-1]!.end))throw new Error('Overlapping supplement slots');
    let result='',cursor=0;
    for(const slot of replacements){result+=skeleton.slice(cursor,slot.start)+slot.value;cursor=slot.end;}
    return result+skeleton.slice(cursor);
}

